export type DiscountKind = "none" | "percent";

export function describeDiscount(kind: DiscountKind) {
  switch (kind) {
    case "none":
      return "No discount";
    case "percent":
      return "Percentage";
  }
}

edits.newText:
export type DiscountKind = "none" | "percent" | "fixed";

export function describeDiscount(kind: DiscountKind) {
  switch (kind) {
    case "none":
      return "No discount";
    case "percent":
      return "Percentage";
    case "fixed":
      return "Fixed amount";
  }
}

